import * as fs from 'node:fs';
import * as path from 'node:path';

export interface CatalogEntry {
  /** Studio questionnaire this question belongs to (e.g. Standard_Quote_DND). */
  questionnaire: string | null;
  questionnaireType: 'QUOTE' | 'APPLICATION' | string | null;
  label: string;
  displayType: string;
  questionType: string;
  section: string | null;
  optionLabels: string[];
  validations: string[];
  isListChild: boolean;
  reflexive: { parent: string | null; condition: string } | null;
}

/** Authoring-time guardrails. Generated by scripts/build-catalog.mjs — never hand-edit. */
export class Catalog {
  private entries: Record<string, CatalogEntry>;

  constructor(file = path.join(__dirname, '../../catalog/naap.questions.json')) {
    this.entries = JSON.parse(fs.readFileSync(file, 'utf8')).questions;
  }

  assertKnown(sureifyId: string) {
    if (!this.entries[sureifyId]) {
      throw new Error(`sureify_id "${sureifyId}" is not in the NAAP catalog — typo, or catalog needs a rebuild (npm run catalog -- <export.json>)`);
    }
  }

  get(sureifyId: string) { return this.entries[sureifyId]; }

  /** Minimum-valid filler for crawl/default fills. Extend per display type as the pilot learns. */
  defaultValueFor(sureifyId: string): string | undefined {
    const e = this.entries[sureifyId];
    if (!e) return undefined;
    if (e.optionLabels.length) return e.optionLabels[0];
    switch (e.displayType) {
      case 'text': return 'Test';
      case 'datepicker': return '1985-04-12';
      case 'currency': return '100000';
      default: return undefined;
    }
  }
}
